using System.Collections.ObjectModel;using System.Text.Json;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class ReplicaViewModel:ObservableObject{readonly AgentDashboardClient c;bool busy;string name="سرور پشتیبان",url="",key="",folder="",status="";ReplicaTargetResponse? target;public ObservableCollection<ReplicaTargetResponse> Targets{get;}=[];public ObservableCollection<ReplicaDatabaseRow> Databases{get;}=[];public ObservableCollection<ReceivedReplicaRow> Received{get;}=[];public string Name{get=>name;set=>Set(ref name,value);}public string Url{get=>url;set=>Set(ref url,value);}public string Key{get=>key;set=>Set(ref key,value);}public string Folder{get=>folder;set=>Set(ref folder,value);}public string Status{get=>status;private set=>Set(ref status,value);}public bool Busy{get=>busy;private set=>Set(ref busy,value);}public ReplicaTargetResponse? Target{get=>target;set{if(Set(ref target,value))_=LoadLinksAsync();}}public ReplicaViewModel(AgentDashboardClient x)=>c=x;public async Task LoadAsync(){Busy=true;try{Targets.Clear();foreach(var x in (await c.ReplicaTargetsAsync()??[]).Where(x=>x.Type==5&&x.IsEnabled))Targets.Add(x);Databases.Clear();foreach(var d in await c.DatabasesFullAsync()??[])Databases.Add(new(d.Id,d.Name,false));Folder=(await c.ReplicaSettingsAsync())?.Directory??"";await LoadReceivedAsync();if(Target is null&&Targets.Count>0)Target=Targets[0];}catch(Exception e){Status=e.Message;}finally{Busy=false;}}public async Task AddTargetAsync(){Busy=true;try{var x=await c.SendAsync<ReplicaTargetResponse>(HttpMethod.Post,"api/storage-targets/odinvault-replica",new{name=Name,baseUrl=Url,apiKey=Key,isEnabled=true,testConnection=false});Key="";Raise(nameof(Key));await LoadAsync();Target=Targets.FirstOrDefault(t=>t.Id==x?.Id);Status="مقصد ثبت شد.";}catch(Exception e){Status=e.Message;}finally{Busy=false;}}async Task LoadLinksAsync(){if(Target is null)return;try{foreach(var d in Databases){var links=await c.SendAsync<JsonElement>(HttpMethod.Get,$"api/databases/{d.Id}/storage-targets");d.Linked=links.EnumerateArray().Any(x=>x.GetProperty("id").GetGuid()==Target.Id&&x.GetProperty("isEnabled").GetBoolean());}}catch(Exception e){Status=e.Message;}}public async Task SaveLinksAsync(){if(Target is null){Status="ابتدا یک مقصد انتخاب کنید.";return;}Busy=true;try{foreach(var d in Databases)if(d.Linked)await c.SendAsync<JsonElement>(HttpMethod.Put,$"api/databases/{d.Id}/storage-targets/{Target.Id}",new{isEnabled=true});else await c.SendAsync<JsonElement>(HttpMethod.Delete,$"api/databases/{d.Id}/storage-targets/{Target.Id}");Status="اتصال دیتابیس‌ها ذخیره شد.";}catch(Exception e){Status=e.Message;}finally{Busy=false;}}public async Task SaveFolderAsync(){Busy=true;try{await c.SendAsync<ReplicaSettingsResponse>(HttpMethod.Put,"api/replica/settings",new{directory=Folder});await LoadReceivedAsync();Status="مسیر دریافت ذخیره شد.";}catch(Exception e){Status=e.Message;}finally{Busy=false;}}async Task LoadReceivedAsync(){Received.Clear();foreach(var x in await c.ReceivedReplicasAsync()??[])Received.Add(new(x.RelativePath,$"{x.SizeBytes/1048576d:0.#} MB",PersianDateFormatter.Format(x.ReceivedAtUtc)));}}internal sealed class ReplicaDatabaseRow:ObservableObject{bool linked;public Guid Id{get;}public string Name{get;}public bool Linked{get=>linked;set=>Set(ref linked,value);}public ReplicaDatabaseRow(Guid id,string name,bool value){Id=id;Name=name;linked=value;}}internal sealed record ReceivedReplicaRow(string Path,string Size,string Date);